target.css:
:root {
  --ink: #26333b;
  --muted: #64727a;
  --paper: #fffdf8;
  --navy: #21485c;
  --sky: #dceef1;
  --line: #bfd4d7;
  --coral: #e97c68;
  --coral-soft: #f9e2dc;
}

.language-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
  background: var(--navy);
}

.kicker {
  margin: 0;
  color: var(--sky);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.state {
  padding: 4px 8px;
  color: var(--navy);
  background: var(--sky);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.session {
  display: grid;
  grid-template-columns: 76px 1fr;
  gap: 10px 14px;
  padding: 14px 16px;
}

.date-block {
  display: flex;
  grid-row: span 2;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 106px;
  color: var(--navy);
  background: var(--sky);
  border-radius: 11px;
}

.date-block span,
.date-block small {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.date-block strong {
  font-size: 31px;
  line-height: 31px;
}

.session-copy h1 {
  margin: 2px 0 3px;
  font-size: 19px;
  line-height: 23px;
}

.session-copy p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.participants {
  display: flex;
  gap: 7px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.participants li {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 6px 8px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 9px;
}

.avatar {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  flex: 0 0 27px;
  color: var(--navy);
  background: var(--sky);
  border-radius: 50%;
  font-size: 10px;
  font-weight: 800;
}

.avatar.coral {
  color: var(--coral);
  background: var(--coral-soft);
}

.person {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.person strong {
  font-size: 12px;
  line-height: 15px;
}

.person small {
  color: var(--muted);
  font-size: 10px;
  line-height: 13px;
  white-space: nowrap;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.room {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.card-footer button {
  padding: 7px 13px;
  color: var(--paper);
  background: var(--coral);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 800;
}

